parameters.jsCode:
// ── 1. Get AI output + clean ──────────────────────────────────
let text = $json.output ?? '';
text = text.replace(/```json/g, '')
           .replace(/```/g, '')
           .replace(/'''/g, '')
           .trim()
           .replace(/\r\n/g, '\n')
           .replace(/\n{3,}/g, '\n\n');

// ── 2. Pull real values from each node ───────────────────────
const piiData  = $('data masking').item.json.piiData       ?? {};
const names    = $('data masking').item.json.detectedNames  ?? [];
const aiFields = $('⚙️ Set — Parsed AI Fields').item.json;

const caseId  = $('📁 BEST — Create Case').item.json.case_id          ?? null;
const capRef  = $('set cap reference').item.json.cap_reference         ?? null;
const slaDate = $('📁 BEST — Create Case').item.json.sla_target_date   ?? null;

// ── 3. Resolve NINO — piiData first, fallback to Set node ─────
const ninoValue = piiData.nino?.values?.[0] ?? aiFields.member_nino ?? null;

// ── 4. Token → real value map ─────────────────────────────────
const tokenMap = {
  '[MEMBER-NINO]': ninoValue,                                // ← matches prompt token
  '[NINO]':        ninoValue,                                // ← legacy fallback
  '[MEMBER-REF]':  piiData.memberId?.values?.[0]      ?? aiFields.member_reference ?? null,
  '[DOB]':         piiData.dob?.values?.[0]            ?? aiFields.member_dob       ?? null,
  '[ADDRESS]':     piiData.address?.values?.[0]        ?? aiFields.current_address  ?? null,
  '[POSTCODE]':    piiData.postcode?.values?.[0]       ?? null,
  '[PHONE]':       piiData.phone?.values?.[0]          ?? null,
  '[SORT-CODE]':   piiData.sortCode?.values?.[0]       ?? null,
  '[ACCOUNT-NO]':  piiData.accountNumber?.values?.[0]  ?? null,
  '[CASE-REF]':    caseId,
  '[CAP-REF]':     capRef,
};

// ── 5. Replace all tokens ─────────────────────────────────────
for (const [token, real] of Object.entries(tokenMap)) {
  if (real !== null && real !== undefined) {
    text = text.split(token).join(real);
  }
}

// ── 6. Return ─────────────────────────────────────────────────
return [{
  json: {
    cleaned_text: text,
    meta: {
      member_name:      aiFields.member_name      ?? names[0] ?? null,
      member_nino:      ninoValue,
      member_reference: aiFields.member_reference ?? null,
      dob:              aiFields.member_dob        ?? null,
      address:          aiFields.current_address   ?? null,
      case_id:          caseId,
      cap_reference:    capRef,
      sla_target_date:  slaDate,
    }
  }
}];

const ai = $('⚙️ Set — Parsed AI Fields').item.json;
const db = $('🗄️ Supabase — Get Member by NINO').item.json;

const normaliseStr  = (s) => (s ?? '').toLowerCase().replace(/\s+/g, ' ').trim();
const normaliseNino = (s) => (s ?? '').toUpperCase().replace(/\s/g, '');

const normaliseDate = (s) => {
  if (!s) return '';
  const str = s.toString().trim();

  // Already YYYY-MM-DD
  if (/^\d{4}-\d{2}-\d{2}$/.test(str)) return str;

  // DD/MM/YYYY or DD-MM-YYYY or DD.MM.YYYY
  const dmy = str.match(/^(\d{1,2})[\/\-\.](\d{1,2})[\/\-\.](\d{4})$/);
  if (dmy) return `${dmy[3]}-${dmy[2].padStart(2,'0')}-${dmy[1].padStart(2,'0')}`;

  // All months — full + abbreviations + edge cases
  const months = {
    january:'01',   february:'02',  march:'03',     april:'04',
    may:'05',       june:'06',       july:'07',      august:'08',
    september:'09', october:'10',   november:'11',  december:'12',
    jan:'01', feb:'02', mar:'03', apr:'04',
    may:'05', jun:'06', jul:'07', aug:'08',
    sep:'09', sept:'09', oct:'10', nov:'11', dec:'12'
  };

  // "12 June 1968" / "12 Jun 1968" / "12 September 1968" / "12 Sept 1968"
  const named = str.match(/^(\d{1,2})\s+([A-Za-z]+)\s+(\d{4})$/);
  if (named) {
    const month = months[named[2].toLowerCase()];
    if (month) return `${named[3]}-${month}-${named[1].padStart(2,'0')}`;
  }

  // "June 12, 1968" / "January 1, 1990"
  const named2 = str.match(/^([A-Za-z]+)\s+(\d{1,2}),?\s+(\d{4})$/);
  if (named2) {
    const month = months[named2[1].toLowerCase()];
    if (month) return `${named2[3]}-${month}-${named2[2].padStart(2,'0')}`;
  }

  return str;
};

// Convert AI dob to YYYY-MM-DD
const normalisedDob = normaliseDate(ai.member_dob);

const name_match    = normaliseStr(ai.member_name)     === normaliseStr(db.member_name);
const dob_match     = normalisedDob                    === normaliseDate(db.member_dob);
const nino_match    = normaliseNino(ai.member_nino)    === normaliseNino(db.member_nino);
const address_match = normaliseStr(ai.current_address) === normaliseStr(db.current_address);

const all_match             = name_match && dob_match && nino_match && address_match;
const address_only_mismatch = !address_match && name_match && dob_match && nino_match;
const address_mismatch      = !address_match;

const mismatch_fields = [
  !name_match    && 'full name',
  !dob_match     && 'date of birth',
  !nino_match    && 'National Insurance number',
  !address_match && 'address',
].filter(Boolean).join(', ');

return [{
  json: {
    ...ai,
    member_dob:            normalisedDob,
    member_id:             db.member_id,
    member_reference:      db.member_reference,
    scheme_code:           db.scheme_code,
    scheme_name:           db.scheme_name,
    db_address:            db.current_address,
    name_match,
    dob_match,
    nino_match,
    address_match,
    all_match,
    mismatch_fields,
    address_mismatch,
    address_only_mismatch,
  }
}];

// ============================================================
// PARSE + UNMASK + FALLBACK (PRODUCTION READY)
// ============================================================

// ── 1. Get AI raw output ─────────────────────────────────────
const raw = $json.output ?? '';

// Remove markdown/code fences
let text = raw
  .replace(/```json/gi, '')
  .replace(/```/g, '')
  .trim();

// Extract JSON block
const match = text.match(/\{[\s\S]*\}/);
if (!match) throw new Error('No JSON object found in AI output');

let parsed;
try {
  parsed = JSON.parse(match[0]);
} catch (err) {
  throw new Error('Invalid JSON: ' + err.message);
}

// ── 2. Get PII data from masking node ────────────────────────
const piiData       = $('data masking').item.json.piiData      ?? {};
const detectedNames = $('data masking').item.json.detectedNames ?? [];

// ── 3. Helper: Resolve value (CRITICAL FIX) ──────────────────
function resolve(value, fallback) {
  if (!value) return fallback ?? null;

  if (typeof value === 'string') {
    const v = value.trim();

    // Treat these as invalid → fallback
    if (
      v === '' ||
      v.toLowerCase() === 'null' ||
      v.includes('[')   // catches [DOB], [ADDRESS], etc.
    ) {
      return fallback ?? null;
    }
  }

  return value;
}

// ── 4. Build final cleaned result ────────────────────────────
const result = {};

// Basic fields
result.member_name = resolve(
  parsed.member_name,
  detectedNames[0] ?? null
);

result.member_nino = resolve(
  parsed.member_nino,
  piiData.nino?.values?.[0]
);

result.member_reference = resolve(
  parsed.member_reference,
  piiData.memberId?.values?.[0]
);

result.member_dob = resolve(
  parsed.member_dob,
  piiData.dob?.values?.[0]
);

result.current_address = resolve(
  parsed.current_address,
  piiData.address?.values?.[0]
);

// Classification fields (no fallback needed usually)
result.sender_type   = parsed.sender_type ?? null;
result.query_type    = parsed.query_type ?? null;
result.query_summary = parsed.query_summary ?? null;

// LOA fields
result.loa_present = parsed.loa_present ?? false;
result.loa_date    = parsed.loa_date ?? null;

// ── 5. Return final output ───────────────────────────────────
return [{
  json: result
}];

// ── AI Confidence Check ─────────────────────────────────────────────────────
// Checks whether the AI extraction has enough data to proceed automatically.
// Low confidence = key fields missing. Route to human checker queue.
// High confidence = continue to normal processing.

const ai = $input.first().json;

const hasName  = ai.member_name  && ai.member_name.trim()  !== '' && ai.member_name  !== 'null';
const hasNino  = ai.member_nino  && ai.member_nino.trim()  !== '' && ai.member_nino  !== 'null';
const hasDob   = ai.member_dob   && ai.member_dob.trim()   !== '' && ai.member_dob   !== 'null';
const hasQuery = ai.query_type   && ai.query_type.trim()   !== '' && ai.query_type   !== 'null' && ai.query_type !== 'unknown';

// Score: count how many key fields were extracted
const fieldScore = [hasName, hasNino, hasDob, hasQuery].filter(Boolean).length;

// Confidence threshold: 3 out of 4 key fields must be present to auto-process
// If less than 3 → low confidence → route to human checker
const confidence_pass = fieldScore >= 3;

const missing_fields = [
  !hasName  && 'member_name',
  !hasNino  && 'member_nino',
  !hasDob   && 'member_dob',
  !hasQuery && 'query_type',
].filter(Boolean).join(', ');

return [{
  json: {
    ...ai,
    confidence_pass,
    confidence_score: fieldScore,
    confidence_missing: missing_fields || 'none',
  }
}];

// ── Read from Normalise Input ─────────────────────────────────
const subject = $('📥 Normalise Input').item.json.subject ?? '';
let body = $('📥 Normalise Input').item.json.text ?? '';
let attachmentText = $('📥 Normalise Input').item.json.attachment_text ?? '';

// ── Strip reply formatting ────────────────────────────────────
function stripFormatting(t) {
  return t
    .replace(/\*\*([^*]+)\*\*/g, '$1')
    .replace(/\*([^*\n]+)\*/g, '$1')
    .replace(/^>\s*/gm, '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/  +/g, ' ')
    .trim();
}
body = stripFormatting(body);
attachmentText = stripFormatting(attachmentText);

const emailText = `SUBJECT: ${subject}\n\nBODY:\n${body}`;
const fullWithAttachment = attachmentText
  ? `${emailText}\n\nATTACHMENT:\n${attachmentText}`
  : emailText;

let masked = fullWithAttachment;
const piiData = {};

function register(key, label, values) {
  const clean = [...new Set(values.map(v => v.trim()).filter(Boolean))];
  if (clean.length === 0) return;
  if (!piiData[key]) piiData[key] = { label, values: [] };
  piiData[key].values = [...new Set([...piiData[key].values, ...clean])];
}

// ── Extract names BEFORE masking ─────────────────────────────
const namesFound = [];
const labelledNameRx = /(?:member\s*name|client\s*name|policyholder|claimant)\s*[:\-]?\s*([A-Z][a-z]+(?:\s+[A-Z][a-z]+)+)/gi;
let nm;
while ((nm = labelledNameRx.exec(fullWithAttachment)) !== null) {
  if (nm[1]) namesFound.push(nm[1].trim());
}
const titledRx = /\b(Mr|Mrs|Ms|Miss|Dr|Prof)\.?\s+[A-Z][a-z]+(?:\s+[A-Z][a-z]+)+/g;
let tn;
while ((tn = titledRx.exec(fullWithAttachment)) !== null) {
  namesFound.push(tn[0].trim());
}
const uniqueNames = [...new Set(namesFound)];

// ── LABELLED patterns only (key:value masking) ────────────────
const labelledPatterns = [
  {
    key: 'nino', label: 'National Insurance Number', token: 'NINO',
    regex: /(?:national\s*insurance\s*(?:number)?|ni(?:no)?(?:\s*(?:number|no))?|n\.i\.(?:\s*(?:number|no))?)\s*[:\-#]?\s*([A-Z]{2}\s?\d{2}\s?\d{2}\s?\d{2}\s?[A-D])/gi,
  },
  {
    key: 'dob', label: 'Date of Birth', token: 'DOB',
    regex: /(?:date\s*of\s*birth|d\.?o\.?b\.?|birth\s*date|born\s*[:\-])\s*(\d{1,2}\s+[A-Za-z]+\s+\d{4}|\d{1,2}[\/\-]\d{1,2}[\/\-]\d{4})/gi,
  },
  {
    key: 'memberId', label: 'Member Reference', token: 'MEMBER-REF',
    regex: /(?:member\s*ref(?:erence)?|mem(?:\s*ref|\s*id|id)|member\s*id|policy(?:\s*no)?|scheme\s*ref)\s*[:\-#]?\s*([A-Z0-9][\w\-\/]{3,25})/gi,
  },
  {
    key: 'address', label: 'Address', token: 'ADDRESS',
    regex: /(?:(?:home|correspondence|postal|mailing)?\s*address)\s*[:\-]?\s*(.+?)(?=\n|$)/gi,
  },
  {
    key: 'phone', label: 'Phone Number', token: 'PHONE',
    regex: /(?:phone|telephone|tel|mobile|mob|contact\s*(?:number)?)\s*[:\-]?\s*((?:\+44\s?|0)[\d\s\-\(\)]{9,15})/gi,
  },
  {
    key: 'postcode', label: 'UK Postcode', token: 'POSTCODE',
    regex: /(?:post\s*code|postal\s*code)\s*[:\-]?\s*([A-Z]{1,2}\d[A-Z\d]?\s?\d[A-Z]{2})/gi,
  },
  {
    key: 'sortCode', label: 'Sort Code', token: 'SORT-CODE',
    regex: /(?:sort\s*code)\s*[:\-]?\s*(\d{2}[\s\-]\d{2}[\s\-]\d{2})/gi,
  },
  {
    key: 'accountNumber', label: 'Account Number', token: 'ACCOUNT-NO',
    regex: /(?:account\s*(?:number|no)?)\s*[:\-]?\s*(\d{8})/gi,
  },
];

for (const p of labelledPatterns) {
  const rx = new RegExp(p.regex.source, p.regex.flags);
  let match;
  const found = [];
  while ((match = rx.exec(masked)) !== null) {
    if (match[1]) found.push(match[1].trim());
  }
  register(p.key, p.label, found);
  masked = masked.replace(
    new RegExp(p.regex.source, p.regex.flags),
    (full, captured) => full.replace(captured, `[${p.token}]`)
  );
}

// ── PII summary ───────────────────────────────────────────────
const summaryLines = [];
if (uniqueNames.length > 0) {
  summaryLines.push(`Member Name [visible]: ${uniqueNames.join(' | ')}`);
}
for (const [, entry] of Object.entries(piiData)) {
  summaryLines.push(`${entry.label}: ${entry.values.join(' | ')}`);
}
const piiSummary = summaryLines.length > 0 ? summaryLines.join('\n') : 'No PII detected';

// ── Build content field ───────────────────────────────────────
const cleanSubject = subject.replace(/^Subject:\s*/i, '').trim();
const content = cleanSubject + '\n\n' + body + (attachmentText ? '\n\nATTACHMENT:\n' + attachmentText : '');

return [{
  json: {
    maskedText: masked,
    piiData,
    piiSummary,
    detectedNames: uniqueNames,
    originalSubject: subject,
    originalBody: body,
    email_subject: cleanSubject,
    email_body: body,
    attachment_text: attachmentText,
    content: content
  }
}];

// ============================================================
// MASK PREVIOUS CORRESPONDENCE
// Masks PII in the previous letter text before sending to AI
// Also outputs tokenMap so unmask node can reverse it
// ============================================================

// ── 1. Get the previous correspondence text ──────────────────
const prevText = $json.data ?? '';

// ── 2. Pull real PII from "data masking" node ─────────────────
const piiData       = $('data masking').item.json.piiData      ?? {};
const detectedNames = $('data masking').item.json.detectedNames ?? [];

// ── 3. Build real value → token map ───────────────────────────
const replaceMap = [];

if (piiData.memberId?.values?.[0])
  replaceMap.push({ val: piiData.memberId.values[0],      token: '[MEMBER-REF]' });

if (piiData.dob?.values?.[0])
  replaceMap.push({ val: piiData.dob.values[0],           token: '[DOB]' });

if (piiData.address?.values?.[0])
  replaceMap.push({ val: piiData.address.values[0],       token: '[ADDRESS]' });

if (piiData.postcode?.values?.[0])
  replaceMap.push({ val: piiData.postcode.values[0],      token: '[POSTCODE]' });

if (piiData.phone?.values?.[0])
  replaceMap.push({ val: piiData.phone.values[0],         token: '[PHONE]' });

if (piiData.nino?.values?.[0])
  replaceMap.push({ val: piiData.nino.values[0],          token: '[NINO]' });

if (piiData.sortCode?.values?.[0])
  replaceMap.push({ val: piiData.sortCode.values[0],      token: '[SORT-CODE]' });

if (piiData.accountNumber?.values?.[0])
  replaceMap.push({ val: piiData.accountNumber.values[0], token: '[ACCOUNT-NO]' });

// ── 4. Apply masking ──────────────────────────────────────────
let maskedPrev = prevText;

for (const { val, token } of replaceMap) {
  const escaped = val.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  maskedPrev = maskedPrev.replace(new RegExp(escaped, 'gi'), token);
}

// ── 5. Raw pattern fallbacks ──────────────────────────────────
maskedPrev = maskedPrev.replace(
  /\b([A-CEGHJ-PR-TW-Z][A-CEGHJ-NPR-TW-Z]\s?\d{2}\s?\d{2}\s?\d{2}\s?[A-D])\b/gi,
  '[NINO]'
);
maskedPrev = maskedPrev.replace(
  /\b([A-Z]{1,2}\d[A-Z\d]?\s?\d[A-Z]{2})\b/gi,
  '[POSTCODE]'
);
maskedPrev = maskedPrev.replace(
  /\b(\d{1,2}[\/\-\.]\d{1,2}[\/\-\.]\d{4})\b/g,
  '[DOB]'
);
maskedPrev = maskedPrev.replace(
  /\b([A-Z]{2,6}[-\/]\d{4}[-\/]\d{3,8})\b/gi,
  '[MEMBER-REF]'
);
maskedPrev = maskedPrev.replace(
  /\b(PCS-[A-Z]+-[A-Z0-9]+)\b/gi,
  '[CASE-REF]'
);
maskedPrev = maskedPrev.replace(
  /(\+44\s?7\d{3}|\(?07\d{3}\)?|\b0[12]\d{3})\s?\d{3}\s?\d{3,4}/g,
  '[PHONE]'
);

// ── 6. Build token → real value map for unmask node ──────────
// This is the reverse: token → real value
const tokenMap = {};
for (const { val, token } of replaceMap) {
  tokenMap[token] = val;
}

// Also store case reference from the text if found
const caseRefMatch = prevText.match(/\b(PCS-[A-Z]+-[A-Z0-9]+)\b/i);
if (caseRefMatch) tokenMap['[CASE-REF]'] = caseRefMatch[1];

// ── 7. Return everything ──────────────────────────────────────
return [{
  json: {
    // → Masked text for letter AI prompt
    maskedPrevCorrespondence: maskedPrev,

    // → Token map for unmask node
    tokenMap,

    // → Individual values for easy access
    realValues: {
      member_reference: piiData.memberId?.values?.[0]      ?? null,
      dob:              piiData.dob?.values?.[0]            ?? null,
      address:          piiData.address?.values?.[0]        ?? null,
      postcode:         piiData.postcode?.values?.[0]       ?? null,
      phone:            piiData.phone?.values?.[0]          ?? null,
      nino:             piiData.nino?.values?.[0]           ?? null,
      member_name:      detectedNames[0]                    ?? null,
      case_reference:   caseRefMatch?.[1]                   ?? null,
    }
  }
}];

// ── 📥 Normalise Input ────────────────────────────────────────
// Receives data from dashboard via webhook
// Fields received: email_subject, email_body, attachment_text,
//                  from_address, session_id, start_time

const payload = $('Webhook — Dashboard').item.json.body || $('Webhook — Dashboard').item.json;

const text          = payload.email_body      || '';
const subject       = payload.email_subject   || '';
const from_address  = payload.from_address    || 'demo@pensionco.co.uk';
const attachment_text = payload.attachment_text || '';
const session_id    = String($execution.id)      || '';
const start_time    = payload.start_time      || Date.now();
const trigger_source = 'webhook';

return [{
  json: {
    text,
    subject,
    from_address,
    attachment_text,
    session_id,
    trigger_source,
    start_time
  }
}];;
